// Hidden suite for T03, written from the spec before the implementation.
import { describe, expect, it } from "vitest";
import { formatTrail, renderTrail } from "../src/breadcrumbs.ts";
import type { Folder, Viewer } from "../src/breadcrumbs.ts";

const ME: Viewer = { id: "u2", isAdmin: false };
const ADMIN: Viewer = { id: "root", isAdmin: true };
const LOCKED = '<span class="crumb locked">private</span>';
const GAP = '<span class="crumb gap">&hellip;</span>';
const item = (name: string) => `<span class="crumb">${name}</span>`;
const shared = (name: string): Folder => ({ name, ownerId: "u1", shared: true });
const mine = (name: string): Folder => ({ name, ownerId: "u2", shared: false });
const theirs = (name: string): Folder => ({ name, ownerId: "u1", shared: false });

describe("renderTrail: visibility", () => {
  it("renders visible folders joined with slashes", () => {
    expect(renderTrail([shared("Home"), mine("Notes")], ME, 5)).toBe(`${item("Home")} / ${item("Notes")}`);
  });

  it("shows shared folders to everyone", () => {
    expect(renderTrail([shared("Team")], { id: "u9", isAdmin: false }, 5)).toBe(item("Team"));
  });

  it("lets admins see every folder", () => {
    expect(renderTrail([theirs("Payroll")], ADMIN, 5)).toBe(item("Payroll"));
  });

  it("hides another user's unshared folder", () => {
    const html = renderTrail([theirs("Payroll")], ME, 5);
    expect(html).toBe(LOCKED);
    expect(html).not.toContain("Payroll");
  });

  it("marks folders the viewer cannot see as private", () => {
    expect(renderTrail([shared("Home"), theirs("Secret"), mine("Notes")], ME, 5)).toBe(
      `${item("Home")} / ${LOCKED} / ${item("Notes")}`,
    );
  });

  it("escapes markup in folder names", () => {
    expect(renderTrail([mine(`<b>"Q&A"</b> it's`)], ME, 5)).toBe(
      item("&lt;b&gt;&quot;Q&amp;A&quot;&lt;/b&gt; it&#39;s"),
    );
  });

  it("renders an empty trail as an empty string", () => {
    expect(renderTrail([], ME, 2)).toBe("");
  });

  it("leaves formatTrail unchanged", () => {
    expect(formatTrail([shared("a"), theirs("b")])).toBe("a / b");
  });
});

describe("renderTrail: shortening", () => {
  const six = ["a", "b", "c", "d", "e", "f"].map(shared);

  it("keeps a trail of exactly maxItems folders whole", () => {
    expect(renderTrail(six, ME, 6)).toBe(["a", "b", "c", "d", "e", "f"].map(item).join(" / "));
  });

  it("keeps the root and the last maxItems - 1 folders when shortening", () => {
    expect(renderTrail(six, ME, 4)).toBe([item("a"), GAP, item("d"), item("e"), item("f")].join(" / "));
  });

  it("shortens to the root and the current folder when maxItems is 2", () => {
    expect(renderTrail(six, ME, 2)).toBe([item("a"), GAP, item("f")].join(" / "));
  });

  it("rejects maxItems below 2 with a RangeError", () => {
    expect(() => renderTrail([], ME, 1)).toThrow(RangeError);
  });

  it("rejects a fractional maxItems", () => {
    expect(() => renderTrail(six, ME, 2.5)).toThrow(RangeError);
  });
});
